from pathlib import Path
program_source = '''def transform(grid):
    grid = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The patterned field is diagonal-periodic; infer its period and colors
    # from the intact lower-right portion.
    best = None
    for period in range(2, 11):
        classes = {}
        for r in range(4, h):
            for c in range(4, w):
                v = grid[r][c]
                if v:
                    classes.setdefault((r + c) % period, {}).setdefault(v, 0)
                    classes[(r + c) % period][v] += 1
        correct = sum(max(counts.values()) for counts in classes.values())
        total = sum(sum(counts.values()) for counts in classes.values())
        score = (correct / total, -period)
        if best is None or score > best[0]:
            best = (score, period, {k: max(counts, key=counts.get) for k, counts in classes.items()})
    _, period, colors = best

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r <= 1:
                grid[r][c] = 1
            elif r == 2 or c == 2:
                grid[r][c] = 4
            elif c <= 1:
                grid[r][c] = 1
            else:
                grid[r][c] = colors[(r + c) % period]
    return grid
'''
